midpoint_oneoff.source_command:
/bin/zsh -lc "/opt/homebrew/bin/python3 -c 'import sys;sys.path.insert(0,\"research\");from math import comb;import json
C=lambda n,k:comb(n,k) if 0<=k<=n else 0
T=lambda j,d,i,h:C(2*d,h)*C(2*i-2-h,i)*(C(j+i+1,2*i-1-h)+C(j+i,2*i-1-h)) if 0<=h<i-1 else 0
out={}
for dr in [\"vertical\",\"diagonal\"]:
 f=[]; ct=0
 for j in range(1,15):
  for d in range(2,15):
   for i in range(2,15):
    for h in range(i+2):
     for k in range(i+2):
      a=(h+k)//2;b=h+k-a
      if dr==\"vertical\":l=T(j,d,i,h)*T(j+2,d-2,i,k);r=T(j+1,d-1,i,a)*T(j+1,d-1,i,b)
      else:l=T(j+2,d-2,i,h)*T(j,d,i+2,k);r=T(j+1,d-1,i+1,a)*T(j+1,d-1,i+1,b)
      ct+=1
      if l>r and len(f)<8:f.append([j,d,i,h,k,l,r])
 out[dr]={\"checks\":ct,\"failures\":f}
print(out)
from pathlib import Path
Path(\"evidence/markov-6799c386/lower-midpoint.json\").write_text(json.dumps(out,indent=2))'"

internal_oneoff.source_command:
/bin/zsh -lc "/opt/homebrew/bin/python3 -c 'import sys;sys.path.insert(0,\"research\");import pair_probe_6799c386 as p; z=[]
for q in range(2,15):
 for i in range(3,2*q+3):
  ps=[]
  for l in range(1,i):
   a=p.conv([p.f(q+1,l,j) for j in range(q+2)],[p.f(q+1,i-l,j) for j in range(q+2)]);b=[0]+p.conv([p.f(q,l,j) for j in range(q+1)],[p.f(q,i-l,j) for j in range(q+1)]);ps.append([p.val(a,j)+p.val(b,j) for j in range(2*q+3)])
  for l,a in enumerate(ps):
   for m,b in enumerate(ps):
    for j in range(2*q+1):
     if a[j]*b[j+2]+b[j]*a[j+2]>2*a[j+1]*b[j+1] and len(z)<10:z.append([q,i,l+1,m+1,j,a[j:j+3],b[j:j+3]])
print(z)'"

regroup_oneoff.source_command:
/bin/zsh -lc "/opt/homebrew/bin/python3 -c 'import sys,json;sys.path.insert(0,\"research\");from column_probe_ec6f4b83 import column;from pathlib import Path
out={\"checks\":0,\"lc_failures\":[],\"mixed_failures\":[]}
for q in range(1,16):
 for i in range(1,2*q+3):
  total,ps=column(q,i);groups=[]
  for r in range(i):
   a,b=ps.get(\"A\"+str(r),{}),ps.get(\"B\"+str(r-1),{});g=[a.get(j,0)+b.get(j,0) for j in range(2*q+3)]
   if any(g):groups.append((r,g))
   for j in range(2*q+1):
    out[\"checks\"]+=1
    if g[j]*g[j+2]>g[j+1]**2 and len(out[\"lc_failures\"])<8:out[\"lc_failures\"].append([q,i,r,j,g[j:j+3]])
  for r,a in groups:
   for s,b in groups:
    for j in range(2*q+1):
     if a[j]*b[j+2]+a[j+2]*b[j]>2*a[j+1]*b[j+1] and len(out[\"mixed_failures\"])<8:out[\"mixed_failures\"].append([q,i,r,s,j,a[j:j+3],b[j:j+3]])
Path(\"evidence/markov-6799c386/regroup-probe.json\").write_text(json.dumps(out,indent=2));print(out)'"

